// The MAC chapter's benchmark set (DOM-free): four kernels (a 16-tap and a 64-tap FIR, an 8th-order biquad cascade, a dot product) as RV32 assembly for five
// machines, each with its data, the exact outputs, and the count of multiply-accumulates. tests/verify/macbench.ts runs them on gates, scripts/mac-bench.ts
// writes the measured figures to dsp/macbench.json, tests/dsp-mac-bench.test.ts re-measures and holds the two equal. Data and outputs are integers
// regenerated by scripts/dsp/oracle.py (tests/dsp/vectors/mac.json) with scipy as the cross-check.
//
// Numbers: samples and taps are 16-bit (Q15), a product is 32 bits, the sum is kept exactly and read once: (sum + 2^14) >> 15, as racc does with shift 15
// (the biquad: Q13 coefficients, shift 13). The FIR taps sum to 1.0 in magnitude and the dot product's values are 12-bit, so even a 32-bit software sum
// cannot overflow: every machine, the 32-bit ones included, must produce the same words. The core has word loads and stores only, so a machine that wants
// 16-bit samples packed in pairs packs them itself, in the data it is given.

import { raccOf } from './mac';

export type MacBench = 'fir16' | 'fir64' | 'biquad' | 'dot';
export type MacMachine = 'rv32i' | 'rv32im' | 'mac' | 'mac2' | 'mac2u';
export const MAC_BENCHES: readonly MacBench[] = ['fir16', 'fir64', 'biquad', 'dot'];
export const MAC_MACHINES: readonly MacMachine[] = ['rv32i', 'rv32im', 'mac', 'mac2', 'mac2u'];

export const MACHINE_NAME: Record<MacMachine, string> = {
  rv32i: 'RV32I, multiply in software', rv32im: 'RV32IM, mul', mac: 'RV32 + MAC, mac', mac2: 'RV32 + MAC, mac2', mac2u: 'RV32 + MAC, mac2 unrolled ×4',
};
export const BENCH_NAME: Record<MacBench, string> = {
  fir16: 'FIR, 16 taps', fir64: 'FIR, 64 taps', biquad: 'Biquad cascade, 4 sections', dot: 'Dot product, 64',
};

/** ROM and data memory of the benchmark runs (2^k words). */
export const MAC_IMEM_K = 10, MAC_DMEM_K = 8;

// ---- the data -----------------------------------------------------------------------------------------------------------------------------

/** The oracle's generator: 16 bits a call, from the top half of an LCG state. */
export function lcg16(seed: number): () => number {
  let s = seed >>> 0;
  return () => { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return (s >>> 16) & 0xffff; };
}

/** A lowpass without trigonometry: ones(k) convolved with itself three times (length T), scaled to a sum of 32768 (Q15), rounded half up. */
export function boxTaps(T: number): number[] {
  const k = (T + 2) / 3, one = Array<number>(k).fill(1);
  const conv = (a: number[], b: number[]) => { const o = Array<number>(a.length + b.length - 1).fill(0); a.forEach((x, i) => b.forEach((y, j) => (o[i + j] += x * y))); return o; };
  const h = conv(conv(one, one), one), S = h.reduce((a, b) => a + b, 0);
  if (h.length !== T) throw new Error(`boxTaps: ${T} is not 3k - 2`);
  return h.map((v) => Math.floor((2 * v * 32768 + S) / (2 * S)));
}

const sum = (xs: readonly (number | bigint)[]): bigint => xs.reduce<bigint>((a, b) => a + BigInt(b), 0n);

export interface FirData { T: number; M: number; h: number[]; x: number[]; y: number[] }
/** y[n] = Σ_k h[k]·x[n + T − 1 − k], n < M, read at shift 15. */
export function firData(T: number, M: number, seed: number): FirData {
  const g = lcg16(seed), L = M + T - 1, x = Array.from({ length: L }, () => g() - 32768);
  x[3] = -32768; x[5] = 32767;
  const h = boxTaps(T);
  const y = Array.from({ length: M }, (_, n) => raccOf(sum(h.map((c, k) => BigInt(c) * BigInt(x[n + T - 1 - k]))), 15).y);
  return { T, M, h, x, y };
}

/** The coefficients of the cascade as the oracle quantizes them (round(c · 2^13) of an 8th-order Butterworth at 0.2, unit gain at DC in every section). */
export const BIQUAD_Q13: readonly (readonly number[])[] = [
  [496, 992, 496, 8408, -2201], [525, 1050, 525, 8904, -2813], [590, 1180, 590, 9992, -4159], [702, 1404, 702, 11891, -6507],
];
export interface BiquadData { N: number; sections: readonly (readonly number[])[]; x: number[]; y: number[]; peak: number }
/** b0 b1 b2 −a1 −a2 in Q13; y = (b0 x + b1 x1 + b2 x2 + (−a1) y1 + (−a2) y2) read at shift 13, section after section, states start at 0. */
export function biquadData(): BiquadData {
  const N = 16, g = lcg16(8), amp = 12000, x = Array.from({ length: N }, () => (g() % (2 * amp + 1)) - amp);
  let cur = x.slice(), peak = 0;
  for (const [b0, b1, b2, na1, na2] of BIQUAD_Q13) {
    let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
    cur = cur.map((v) => {
      const y = raccOf(BigInt(b0 * v + b1 * x1 + b2 * x2 + na1 * y1 + na2 * y2), 13).y;
      if (y < -32768 || y > 32767) throw new Error('biquad: a state left 16 bits');
      peak = Math.max(peak, Math.abs(y));
      [x2, x1, y2, y1] = [x1, v, y1, y];
      return y;
    });
  }
  return { N, sections: BIQUAD_Q13, x, y: cur, peak };
}

export interface DotData { N: number; a: number[]; b: number[]; y: number }
export function dotData(): DotData {
  const g = lcg16(99), N = 64, a = Array.from({ length: N }, () => (g() % 8191) - 4095), b = Array.from({ length: N }, () => (g() % 8191) - 4095);
  return { N, a, b, y: raccOf(sum(a.map((v, i) => BigInt(v) * BigInt(b[i]))), 15).y };
}

// ---- the programs -------------------------------------------------------------------------------------------------------------------------

export interface MacPlan {
  bench: MacBench;
  machine: MacMachine;
  /** Setup (the data into memory), the kernel, and the halt: `source`; `setupSource` is the setup alone, so that the kernel's cycles are the difference. */
  source: string;
  setupSource: string;
  /** Output words (word index → value) the kernel leaves at 0 .. outputs − 1. */
  expect: Map<number, number>;
  outputs: number;
  /** Multiply-accumulates the kernel performs (taps × outputs, 5 × samples × sections, elements). */
  products: number;
  /** Taps (or products) that one pass of the inner loop does, for "cycles in the inner loop". */
  inner: { name: string; instructions: number; per: number } | null;
}

const pack = (lo: number, hi: number) => (((hi & 0xffff) << 16) | (lo & 0xffff)) >>> 0;
const u32 = (v: number) => v >>> 0;

/** Software 16 × 16 signed multiply, inline: t2 = a × b (a, b: registers holding int16 values; they are copied, so neither changes). Uses a5, a6, a7, t6. */
function swMul(a: string, b: string, tag: string): string[] {
  return [
    `mv a5, ${a}`, `mv a6, ${b}`, 'li t2, 0', 'li t6, 15',
    `${tag}a: andi a7, a6, 1`, `beqz a7, ${tag}b`, 'add t2, t2, a5',
    `${tag}b: slli a5, a5, 1`, 'srai a6, a6, 1', 'addi t6, t6, -1', `bnez t6, ${tag}a`,
    // bit 15 of the multiplier is the sign: it weighs −2^15
    'andi a7, a6, 1', `beqz a7, ${tag}c`, 'sub t2, t2, a5', `${tag}c:`,
  ];
}

/** mac2 over `words` words: t3 data, t4 coefficients, t5 the coefficient run's end; U words per pass of the loop (the rest peeled off in front). */
function mac2Words(tag: string, words: number, U: number): string[] {
  const out: string[] = [];
  const one = (off: number) => [`lw t0, ${off}(t3)`, `lw t1, ${off}(t4)`, 'mac2 t0, t1'];
  if (U === 1) return [`${tag}: ${one(0)[0]}`, ...one(0).slice(1), 'addi t3, t3, 4', 'addi t4, t4, 4', `bne t4, t5, ${tag}`];
  const peel = words % U;
  for (let i = 0; i < peel; i++) out.push(...one(4 * i));
  if (peel) out.push(`addi t3, t3, ${4 * peel}`, `addi t4, t4, ${4 * peel}`);
  if (words - peel > 0) {
    for (let i = 0; i < U; i++) out.push(...(i === 0 ? one(0).map((s, k) => (k === 0 ? `${tag}: ${s}` : s)) : one(4 * i)));
    out.push(`addi t3, t3, ${4 * U}`, `addi t4, t4, ${4 * U}`, `bne t4, t5, ${tag}`);
  }
  return out;
}

const setupOf = (mem: Map<number, number>): string[] => {
  const out: string[] = [];
  for (const [a, v] of [...mem].sort((p, q) => p[0] - q[0])) if (v !== 0) out.push(`li t0, ${v | 0}`, `sw t0, ${4 * a}(zero)`);
  return out;
};

const finish = (bench: MacBench, machine: MacMachine, mem: Map<number, number>, kernel: string[], expect: number[], products: number, inner: MacPlan['inner']): MacPlan => {
  const setup = setupOf(mem), end = ['end: j end'];
  return {
    bench, machine, source: [...setup, ...kernel, ...end].join('\n') + '\n', setupSource: [...setup, ...end].join('\n') + '\n',
    expect: new Map(expect.map((v, i) => [i, u32(v)])), outputs: expect.length, products, inner,
  };
};

function firPlan(bench: 'fir16' | 'fir64', m: MacMachine): MacPlan {
  const d = bench === 'fir16' ? firData(16, 16, 16) : firData(64, 8, 64), { T, M } = d, L = M + T - 1;
  const hr = d.h.slice().reverse(); // hr[j] = h[T − 1 − j]: both arrays ascend
  const mem = new Map<number, number>();
  const packed = m === 'mac2' || m === 'mac2u';
  const X0 = 32;
  const k: string[] = [];
  let inner: MacPlan['inner'];
  if (packed) {
    const xp = [...d.x, 0], XW = xp.length / 2, E0 = X0 + XW, O0 = E0 + T / 2, U = m === 'mac2u' ? 4 : 1;
    for (let w = 0; w < XW; w++) mem.set(X0 + w, pack(xp[2 * w], xp[2 * w + 1]));
    // output 2r: words (hr[2i], hr[2i+1]); output 2r + 1: words (hr[2i−1], hr[2i]), one more word, the first and last half empty
    for (let i = 0; i < T / 2; i++) mem.set(E0 + i, pack(hr[2 * i], hr[2 * i + 1]));
    for (let i = 0; i <= T / 2; i++) mem.set(O0 + i, pack(i > 0 ? hr[2 * i - 1] : 0, i < T ? hr[2 * i] : 0));
    k.push(`li a0, ${4 * X0}`, 'li a3, 0', `li a4, ${4 * M}`, 'li s9, 15',
      'pair: clracc', 'mv t3, a0', `li t4, ${4 * E0}`, `li t5, ${4 * (E0 + T / 2)}`, ...mac2Words('ea', T / 2, U), 'racc t6, s9', 'sw t6, 0(a3)',
      'clracc', 'mv t3, a0', `li t4, ${4 * O0}`, `li t5, ${4 * (O0 + T / 2 + 1)}`, ...mac2Words('oa', T / 2 + 1, U), 'racc t6, s9', 'sw t6, 4(a3)',
      'addi a0, a0, 4', 'addi a3, a3, 8', 'bne a3, a4, pair');
    inner = { name: m === 'mac2u' ? 'four words (eight taps)' : 'one word (two taps)', instructions: m === 'mac2u' ? 3 * 4 + 3 : 6, per: m === 'mac2u' ? 8 : 2 };
  } else {
    const H0 = X0 + L;
    d.x.forEach((v, i) => mem.set(X0 + i, u32(v)));
    hr.forEach((v, j) => mem.set(H0 + j, u32(v)));
    const head = [`li a0, ${4 * X0}`, 'li a3, 0', `li a4, ${4 * M}`, 'li s9, 15', 'out: mv t3, a0', `li t4, ${4 * H0}`, `li t5, ${4 * (H0 + T)}`];
    const tail = ['sw t6, 0(a3)', 'addi a0, a0, 4', 'addi a3, a3, 4', 'bne a3, a4, out'];
    if (m === 'mac') {
      k.push(...head.slice(0, 5), 'clracc', ...head.slice(5), 'tap: lw t0, 0(t3)', 'lw t1, 0(t4)', 'mac t0, t1', 'addi t3, t3, 4', 'addi t4, t4, 4', 'bne t4, t5, tap', 'racc t6, s9', ...tail);
      inner = { name: 'one tap', instructions: 6, per: 1 };
    } else if (m === 'rv32im') {
      k.push(...head, 'li s0, 0', 'tap: lw t0, 0(t3)', 'lw t1, 0(t4)', 'mul t2, t0, t1', 'add s0, s0, t2', 'addi t3, t3, 4', 'addi t4, t4, 4', 'bne t4, t5, tap',
        'li t2, 16384', 'add s0, s0, t2', 'srai t6, s0, 15', ...tail);
      inner = { name: 'one tap', instructions: 7, per: 1 };
    } else {
      k.push(...head, 'li s0, 0', 'tap: lw t0, 0(t3)', 'lw t1, 0(t4)', ...swMul('t0', 't1', 'm'), 'add s0, s0, t2', 'addi t3, t3, 4', 'addi t4, t4, 4', 'bne t4, t5, tap',
        'li t2, 16384', 'add s0, s0, t2', 'srai t6, s0, 15', ...tail);
      inner = { name: 'one tap (a multiply of 15 steps)', instructions: 0, per: 1 };
    }
  }
  return finish(bench, m, mem, k, d.y, M * T, inner);
}

function dotPlan(m: MacMachine): MacPlan {
  const d = dotData(), N = d.N, mem = new Map<number, number>(), A0 = 32, k: string[] = [];
  let inner: MacPlan['inner'];
  if (m === 'mac2' || m === 'mac2u') {
    const B0 = A0 + N / 2, U = m === 'mac2u' ? 4 : 1;
    for (let w = 0; w < N / 2; w++) { mem.set(A0 + w, pack(d.a[2 * w], d.a[2 * w + 1])); mem.set(B0 + w, pack(d.b[2 * w], d.b[2 * w + 1])); }
    k.push('li s9, 15', `li t3, ${4 * A0}`, `li t4, ${4 * B0}`, `li t5, ${4 * (B0 + N / 2)}`, 'clracc', ...mac2Words('dt', N / 2, U), 'racc t6, s9', 'sw t6, 0(zero)');
    inner = { name: m === 'mac2u' ? 'four words (eight products)' : 'one word (two products)', instructions: m === 'mac2u' ? 15 : 6, per: m === 'mac2u' ? 8 : 2 };
  } else {
    const B0 = A0 + N;
    d.a.forEach((v, i) => { mem.set(A0 + i, u32(v)); mem.set(B0 + i, u32(d.b[i])); });
    const head = [`li t3, ${4 * A0}`, `li t4, ${4 * B0}`, `li t5, ${4 * (B0 + N)}`];
    const adv = ['addi t3, t3, 4', 'addi t4, t4, 4', 'bne t4, t5, dt'];
    if (m === 'mac') { k.push('li s9, 15', ...head, 'clracc', 'dt: lw t0, 0(t3)', 'lw t1, 0(t4)', 'mac t0, t1', ...adv, 'racc t6, s9', 'sw t6, 0(zero)'); inner = { name: 'one product', instructions: 6, per: 1 }; }
    else if (m === 'rv32im') { k.push(...head, 'li s0, 0', 'dt: lw t0, 0(t3)', 'lw t1, 0(t4)', 'mul t2, t0, t1', 'add s0, s0, t2', ...adv, 'li t2, 16384', 'add s0, s0, t2', 'srai t6, s0, 15', 'sw t6, 0(zero)'); inner = { name: 'one product', instructions: 7, per: 1 }; }
    else { k.push(...head, 'li s0, 0', 'dt: lw t0, 0(t3)', 'lw t1, 0(t4)', ...swMul('t0', 't1', 'm'), 'add s0, s0, t2', ...adv, 'li t2, 16384', 'add s0, s0, t2', 'srai t6, s0, 15', 'sw t6, 0(zero)'); inner = { name: 'one product (a multiply of 15 steps)', instructions: 0, per: 1 }; }
  }
  return finish('dot', m, mem, k, [d.y], N, inner);
}

function biquadPlan(m: MacMachine): MacPlan {
  const d = biquadData(), N = d.N, S = d.sections.length, mem = new Map<number, number>(), CB = 32;
  d.x.forEach((v, i) => mem.set(i, u32(v))); // the signal lives in words 0 … N − 1 and is filtered in place, section after section
  const packed = m === 'mac2' || m === 'mac2u';
  const per = packed ? 3 : 5;
  d.sections.forEach((c, s) => {
    if (packed) { mem.set(CB + 3 * s, u32(c[0])); mem.set(CB + 3 * s + 1, pack(c[1], c[2])); mem.set(CB + 3 * s + 2, pack(c[3], c[4])); }
    else c.forEach((v, j) => mem.set(CB + 5 * s + j, u32(v)));
  });
  const k: string[] = [`li a2, ${4 * CB}`, `li a3, ${4 * (CB + per * S)}`, 'li s9, 13'];
  const loads = packed ? ['lw s0, 0(a2)', 'lw s1, 4(a2)', 'lw s2, 8(a2)'] : ['lw s0, 0(a2)', 'lw s1, 4(a2)', 'lw s2, 8(a2)', 'lw s3, 12(a2)', 'lw s4, 16(a2)'];
  k.push('sec:', ...loads, ...(packed ? ['li s5, 0', 'li s7, 0'] : ['li s5, 0', 'li s6, 0', 'li s7, 0', 'li s8, 0']), 'li a0, 0', `li a1, ${4 * N}`);
  let body: string[];
  if (m === 'mac') {
    body = ['lw t0, 0(a0)', 'clracc', 'mac t0, s0', 'mac s5, s1', 'mac s6, s2', 'mac s7, s3', 'mac s8, s4', 'racc t1, s9', 'mv s6, s5', 'mv s5, t0', 'mv s8, s7', 'mv s7, t1', 'sw t1, 0(a0)', 'addi a0, a0, 4'];
  } else if (packed) {
    // x in s0 alone; (x1, x2) packed in s5 against (b1, b2) in s1; (y1, y2) packed in s7 against (−a1, −a2) in s2. The pairs shift up by 16 bits and take the new value in.
    body = ['lw t0, 0(a0)', 'clracc', 'mac t0, s0', 'mac2 s5, s1', 'mac2 s7, s2', 'racc t1, s9',
      'slli t3, s5, 16', 'slli t4, t0, 16', 'srli t4, t4, 16', 'or s5, t3, t4', 'slli t3, s7, 16', 'slli t4, t1, 16', 'srli t4, t4, 16', 'or s7, t3, t4', 'sw t1, 0(a0)', 'addi a0, a0, 4'];
  } else {
    const prod = (c: string, s: string, i: number) => (m === 'rv32im' ? [`mul t2, ${c}, ${s}`] : swMul(c, s, `q${i}`));
    body = ['lw t0, 0(a0)', 'li s10, 0', ...[['s0', 't0'], ['s1', 's5'], ['s2', 's6'], ['s3', 's7'], ['s4', 's8']].flatMap(([c, s], i) => [...prod(c, s, i), 'add s10, s10, t2']),
      'li t5, 4096', 'add s10, s10, t5', 'srai t1, s10, 13', 'mv s6, s5', 'mv s5, t0', 'mv s8, s7', 'mv s7, t1', 'sw t1, 0(a0)', 'addi a0, a0, 4'];
  }
  // unrolled: two samples a pass (the loop test and the pointer step are paid once)
  if (m === 'mac2u') {
    const one = body.slice(0, -1), shift = (b: string[]) => b.map((s) => s.replace('0(a0)', '4(a0)'));
    k.push('smp:', ...one, ...shift(one), 'addi a0, a0, 8', 'bne a0, a1, smp');
  } else k.push('smp:', ...body, 'bne a0, a1, smp');
  k.push(`addi a2, a2, ${4 * per}`, 'bne a2, a3, sec');
  return finish('biquad', m, mem, k, d.y, N * S * 5, { name: 'one sample through one section', instructions: m === 'mac' ? 15 : m === 'mac2' ? 17 : m === 'mac2u' ? 16 : 0, per: 5 });
}

/** The program of one benchmark on one machine. */
export function macPlan(bench: MacBench, machine: MacMachine): MacPlan {
  return bench === 'dot' ? dotPlan(machine) : bench === 'biquad' ? biquadPlan(machine) : firPlan(bench, machine);
}
